export const TAU=Math.PI*2;
export const clamp=(v,min,max,fallback=min)=>Math.min(max,Math.max(min,v!==null&&v!==''&&Number.isFinite(Number(v))?Number(v):fallback));
// dB-Wert relativ zum stärksten Anteil (halbe Amplitude −6 dB, ein Zehntel −20 dB); null bei Stille.
export const relativeDb=(a,max)=>a>0&&max>0?Math.round(20*Math.log10(a/max)):null;
export const SHAPES=['sine','triangle','saw','square'],MAX_WAVES=16,HARMONICS=25;
// Ein Klang ist eine Liste überlagerter Wellen. Dreieck, Sägezahn und Rechteck entstehen aus endlich vielen
// Sinus-Teiltönen (Fourier-Koeffizienten, Spitzenwert ≈ 1); die Phase einer Welle verschiebt sie zeitlich,
// Teilton n also um n·Phase, damit die Form erhalten bleibt.
export function shapePartials(shape,count=HARMONICS){if(shape==='sine'||!SHAPES.includes(shape))return [{n:1,a:1,p:0}];const out=[];for(let n=1;n<=count;n++){let a=0,p=0;if(shape==='saw')a=2/Math.PI/n;if(shape==='square')a=n%2?4/Math.PI/n:0;if(shape==='triangle'){a=n%2?8/Math.PI**2/(n*n):0;p=n%4===3?180:0;}if(a)out.push({n,a,p});}return out;}
// Obergrenze der Teiltöne insgesamt: so viele sin() pro Sample verkraften Audio-Thread und Anzeige auch auf Tablets.
// Bei Überschreitung verlieren alle Formen gemeinsam hohe Teiltöne; Sinuswellen zählen nur einmal.
export const MAX_PARTIALS=160;
// Überschwinger (Gibbs) der endlichen Näherungen, damit die Summe nicht übersteuert.
const PEAK={sine:1,triangle:1,saw:1.18,square:1.18};
export const makeWave=(f=220,shape='sine',a=1,p=0)=>({shape,f,a,p,mute:false,solo:false});
// Klingende Wellen mit Teiltönen unter Nyquist; index zeigt auf die Welle im Klang, Phasen in Bogenmass.
// ignoreSolo: alle klingenden Wellen, auch wenn eine andere solo ist (Anzeige: Geisterlinien, Auto-Bereich, Treffer im Spektrum).
export function activeWaves(s,sampleRate=48000,ignoreSolo=false){const solo=!ignoreSolo&&s.waves.some(w=>w.solo),live=s.waves.map((w,index)=>({w,index})).filter(({w})=>w.a>0&&!w.mute&&(!solo||w.solo)),full=live.map(({w})=>shapePartials(w.shape).filter(q=>q.n*w.f<sampleRate/2)),size=c=>full.reduce((n,p)=>n+p.filter(q=>q.n<=c).length,0);let count=HARMONICS;while(count>1&&size(count)>MAX_PARTIALS)count--;return live.map(({w,index},i)=>({index,f:w.f,peak:w.a*PEAK[w.shape],parts:full[i].filter(q=>q.n<=count).map(q=>({n:q.n,a:q.a*w.a,p:(q.p+q.n*w.p)*TAU/360}))})).filter(w=>w.parts.length);}
export function activePartials(s,sampleRate=48000){return activeWaves(s,sampleRate).flatMap(w=>w.parts.map(q=>({a:q.a,f:q.n*w.f,p:q.p,wave:w.index})));}
export function normalization(waves){return 1/Math.max(1,waves.reduce((sum,w)=>sum+w.peak,0));}
export function generateSamples(s,size,sampleRate=48000,offset=0){const waves=activeWaves(s,sampleRate),norm=normalization(waves),out=new Float32Array(size);for(let i=0;i<size;i++){const time=i/sampleRate+offset;let sum=0;for(const w of waves)for(const q of w.parts)sum+=q.a*Math.sin(q.n*TAU*w.f*time+q.p);out[i]=sum*norm;}return out;}
// FFT matches Web Audio's Blackman window and 1/N magnitude convention.
export function spectrum(samples){const n=samples.length;if(n<2||(n&(n-1)))throw new Error('FFT size must be a power of two');const re=new Float64Array(n),im=new Float64Array(n);for(let i=0;i<n;i++)re[i]=samples[i]*(.42-.5*Math.cos(TAU*i/n)+.08*Math.cos(2*TAU*i/n));for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)[re[i],re[j]]=[re[j],re[i]];}for(let len=2;len<=n;len<<=1){const angle=-TAU/len,wr=Math.cos(angle),wi=Math.sin(angle);for(let i=0;i<n;i+=len){let ur=1,ui=0;for(let j=0;j<len/2;j++){const k=i+j,l=k+len/2,tr=re[l]*ur-im[l]*ui,ti=re[l]*ui+im[l]*ur;re[l]=re[k]-tr;im[l]=im[k]-ti;re[k]+=tr;im[k]+=ti;const next=ur*wr-ui*wi;ui=ur*wi+ui*wr;ur=next;}}}return Float32Array.from({length:n/2},(_,i)=>20*Math.log10(Math.max(1e-8,Math.hypot(re[i],im[i])/n)));}
// Frühere Klänge (Grundfrequenz + Teiltonbalken) aus Links und Speicher: Vorgabe als eine Welle, sonst je Teilton eine Sinuswelle.
function fromPartials(input){if(input.partials.length<1||input.partials.length>32)throw new Error('Invalid sound');const f0=clamp(input.fundamental,20,20000,220),harmonic=input.harmonic!==false;if(harmonic&&SHAPES.includes(input.preset)&&!input.partials.some(p=>p?.mute||p?.solo))return [makeWave(f0,input.preset)];const waves=input.partials.map((p,i)=>({shape:'sine',f:harmonic?f0*(i+1):p?.f??f0*(i+1),a:p?.a,p:p?.p,mute:p?.mute,solo:p?.solo})).filter(w=>clamp(w.a,0,1)>0&&Number(w.f)>=20&&Number(w.f)<=20000);if(waves.length<=MAX_WAVES)return waves;const strongest=[...waves].sort((a,b)=>clamp(b.a,0,1)-clamp(a.a,0,1)).slice(0,MAX_WAVES);return waves.filter(w=>strongest.includes(w));}
export function validateSound(input){if(!input||typeof input!=='object')throw new Error('Invalid sound');const waves=Array.isArray(input.waves)?input.waves:Array.isArray(input.partials)?fromPartials(input):null;if(!waves||waves.length>MAX_WAVES)throw new Error('Invalid sound');return{waves:waves.map(w=>({shape:SHAPES.includes(w?.shape)?w.shape:'sine',f:Math.round(clamp(w?.f,20,20000,220)*10)/10,a:Math.round(clamp(w?.a,0,1)*100)/100,p:Math.round(clamp(w?.p,-180,180,0)),mute:!!w?.mute,solo:!!w?.solo}))};}
export function wavBuffer(samples,sampleRate=48000){const buffer=new ArrayBuffer(44+samples.length*2),v=new DataView(buffer);function str(at,s){for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i));}str(0,'RIFF');v.setUint32(4,36+samples.length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,samples.length*2,true);for(let i=0;i<samples.length;i++)v.setInt16(44+i*2,clamp(samples[i],-1,1)*(samples[i]<0?32768:32767),true);return buffer;}
